export const PLUGIN_PROTO = "// Landflow plugin protocol — v1\n//\n// A plugin is a process that hosts one or more node types. The Landflow host\n// discovers plugins, pulls their manifest, renders the node UI from the\n// descriptors and calls Execute when a workflow reaches one of their nodes.\n//\n// The same contract is exposed over HTTP+JSON (see docs/protocol.md). Anything\n// recursive or open-ended (node descriptors, parameters, item payloads) travels\n// as a JSON-encoded DynamicValue so both transports share one JSON Schema\n// (packages/protocol/schema/*.json). This mirrors Terraform's tfplugin\n// DynamicValue approach: a typed envelope, a dynamic payload.\nsyntax = \"proto3\";\n\npackage landflow.plugin.v1;\n\noption go_package = \"github.com/landflow/landflow/sdks/go/landflowpb;landflowpb\";\n\n// Implemented by every plugin.\nservice PluginService {\n  // Describe the plugin and every node type it provides.\n  rpc GetManifest(GetManifestRequest) returns (GetManifestResponse);\n  // Run one node over a batch of input items.\n  rpc Execute(ExecuteRequest) returns (ExecuteResponse);\n  // Resolve a dynamic dropdown (property.typeOptions.loadOptionsMethod).\n  rpc LoadOptions(LoadOptionsRequest) returns (LoadOptionsResponse);\n  // Liveness probe used by discovery and the registry heartbeat.\n  rpc Health(HealthRequest) returns (HealthResponse);\n  // Check credential values against the service (\"Test connection\").\n  rpc TestCredentials(TestCredentialsRequest) returns (TestCredentialsResponse);\n}\n\n// Trace context: the host sends W3C traceparent / tracestate / baggage as gRPC\n// metadata (HTTP headers on the HTTP binding) with every call, so plugin spans\n// join the workflow's trace. See docs/observability.md.\n\n// Implemented by the Landflow host (default :7070). Plugins announce\n// themselves here; the HTTP equivalent is POST /api/plugins/announce.\nservice RegistryService {\n  rpc Announce(AnnounceRequest) returns (AnnounceResponse);\n  rpc Withdraw(WithdrawRequest) returns (WithdrawResponse);\n}\n\n// JSON-encoded value. `json` holds UTF-8 JSON bytes.\nmessage DynamicValue {\n  bytes json = 1;\n}\n\nmessage PluginInfo {\n  string id = 1;          // stable, url-safe: \"go-crypto\"\n  string name = 2;        // display name: \"Crypto Toolkit\"\n  string version = 3;     // semver of the plugin\n  string description = 4;\n  string language = 5;    // \"typescript\" | \"python\" | \"go\" | ...\n  string sdk_name = 6;    // \"landflow-sdk-go\"\n  string sdk_version = 7;\n  string icon = 8;        // \"lucide:hash\" | \"emoji:🔐\" | https/data URL (SDKs inline file: icons)\n  string author = 9;\n  string homepage = 10;\n  string color = 11;      // brand colour (hex): \"#0d9488\"\n}\n\n// ---- Manifest ---------------------------------------------------------\n\nmessage GetManifestRequest {\n  string host_version = 1;\n}\n\nmessage GetManifestResponse {\n  string protocol = 1;             // \"landflow.plugin/v1\"\n  PluginInfo plugin = 2;\n  repeated DynamicValue nodes = 3; // each: a NodeDescriptor JSON object\n  repeated DynamicValue credential_types = 4; // each: a CredentialTypeDescriptor JSON object\n}\n\n// ---- Execute ----------------------------------------------------------\n\nmessage NodeRef {\n  string id = 1;\n  string name = 2;         // unique display name inside the workflow\n  string type = 3;         // fully-qualified: \"<pluginId>.<nodeName>\"\n  int32 type_version = 4;\n}\n\nmessage PairedItem {\n  int32 item = 1;\n  int32 input = 2;\n}\n\nmessage Item {\n  DynamicValue json = 1;   // the item payload (a JSON object)\n  PairedItem paired_item = 2;\n}\n\nmessage Branch {\n  repeated Item items = 1;\n}\n\nmessage ExecuteRequest {\n  string protocol = 1;\n  string execution_id = 2;\n  string workflow_id = 3;\n  string mode = 4;                               // \"manual\" | \"trigger\" | \"webhook\" | \"tool\" | \"chat\" | \"poll\"\n  NodeRef node = 5;\n  DynamicValue parameters = 6;                   // resolved against item 0 (or no item)\n  repeated DynamicValue item_parameters = 7;     // resolved per item of input 0\n  repeated Branch inputs = 8;                    // inputs[i] = items arriving on main input i\n  DynamicValue credentials = 9;                  // optional: { <credentialType>: { ...decrypted fields } }\n  DynamicValue poll_state = 10;                  // poll triggers: state returned by the previous poll\n  bool continue_on_fail = 11;                    // emit { json: { error } } for a failing item and go on\n}\n\nmessage LogEntry {\n  string level = 1;        // \"debug\" | \"info\" | \"warn\" | \"error\"\n  string message = 2;\n}\n\nmessage NodeError {\n  string message = 1;\n  string description = 2;\n  int32 item_index = 3;    // -1 when not item-specific\n}\n\nmessage ExecuteResponse {\n  repeated Branch outputs = 1;   // outputs[i] = items emitted on main output i\n  repeated LogEntry logs = 2;\n  NodeError error = 3;           // set when the node failed as a whole\n  DynamicValue poll_state = 4;   // poll triggers: state for the next poll\n}\n\n// ---- Load options -----------------------------------------------------\n\nmessage LoadOptionsRequest {\n  string node_type = 1;            // local node name (without plugin prefix)\n  string method = 2;\n  DynamicValue parameters = 3;     // current (unresolved) parameter values\n  DynamicValue credentials = 4;    // optional, same shape as ExecuteRequest.credentials\n}\n\nmessage LoadOptionsResponse {\n  DynamicValue options = 1;        // JSON array of { name, value, description? }\n}\n\n// ---- Credentials ------------------------------------------------------\n\nmessage TestCredentialsRequest {\n  string credential_type = 1;      // local credential type name\n  DynamicValue data = 2;           // the credential values to test\n}\n\nmessage TestCredentialsResponse {\n  bool ok = 1;\n  string message = 2;\n}\n\n// ---- Health -----------------------------------------------------------\n\nmessage HealthRequest {}\n\nmessage HealthResponse {\n  string status = 1;       // \"ok\" | \"degraded\"\n  int64 uptime_ms = 2;\n  string plugin_id = 3;\n  string version = 4;\n}\n\n// ---- Registry ---------------------------------------------------------\n\nmessage AnnounceRequest {\n  string protocol = 1;\n  string endpoint = 2;     // \"http://127.0.0.1:7101\" or \"grpc://127.0.0.1:7203\"\n  string plugin_id = 3;\n  string version = 4;\n  int32 ttl_seconds = 5;   // lease; re-announce before it expires (default 30)\n}\n\nmessage AnnounceResponse {\n  bool accepted = 1;\n  int32 heartbeat_interval_seconds = 2;\n  string message = 3;\n}\n\nmessage WithdrawRequest {\n  string endpoint = 1;\n  string plugin_id = 2;\n}\n\nmessage WithdrawResponse {\n  bool ok = 1;\n}\n";
